public static SimpleDateFormat dateFormatFromString(String date) {
        if (date.find("([0-3]?[0-9][A-Z]{3}[0-9]{4})")) {
            return new SimpleDateFormat("ddMMMyyyy")
        } else if (date.find("([0-3]?[0-9] [A-z]{3,4} [0-9]{4})")) {
            return new SimpleDateFormat("dd MMM yyyy")
        } else if (date.find("[0-3][0-9]/[0-1][0-9]/[0-9]{4}")) {
            return new SimpleDateFormat("dd/MM/yyyy")
        } else if (date.find("[0-3][0-9]-[0-1][0-9]-[0-9]{4}")) {
            return new SimpleDateFormat("dd-MM-yyyy")
        } else if (date.find("[0-3][0-9]/[0-1][0-9]/[0-9]{2}")) {
            return new SimpleDateFormat("dd/MM/yy")
        } else if (date.find("([0-3]?[0-9]-[\\s]*[A-z]{3,4}-[\\s]*[0-9]{2,4})")) {
            return new SimpleDateFormat("dd-MMM-yyyy")
        }
        else if (date.find("([0-3]?[0-9]-[A-z]{3,4}-[0-9]{2,4})")) {
            return new SimpleDateFormat("yyyy-MM-dd")
        }
        else if (date.find("([0-9]{4}-[0-1][0-9]-[0-3][0-9])")) {
            return new SimpleDateFormat("yyyy-MM-dd")
        } else if (date.find("[0-1]?[0-9]/[0-3]?[0-9]/[0-9]{4}")) {
            return new SimpleDateFormat("MM/dd/yyyy")
        } else if (date.find("[0-1]?[0-9]-[0-3]?[0-9]-[0-9]{4}")) {
            return new SimpleDateFormat("MM-dd-yyyy")
        } else if (date.find("[0-1]?[0-9] [A-z]{3} '[0-9]{2}")) {
            return new SimpleDateFormat("dd MMM ''yy")
        } else if (date.find("[0-3]?[0-9]-[0-1]?[0-9]-[0-9]{2}")) {
            return new SimpleDateFormat("dd-MM-yy")
        } else if (date.find("([0-3]?[0-9] [A-z]{3,4} [0-9]{2})")) {
            return new SimpleDateFormat("dd MMM yy")
        }
    }

