public
    static void extractTransactionsFromHTMLHavingDescriptionAboveDate(ProcessedBankStatementVO processedBankStatementVO) {
        String result = PDF2Table.fetchTransactionHTML(processedBankStatementVO.processBankStatementCO.bankStatement, processedBankStatementVO.processBankStatementCO.password)
        Map<String, String> headerMap = headerDictionary()
        JSONArray resultList = new JSONArray(result)
        for (int i = 0; i < resultList.length(); i++) {
            org.jsoup.nodes.Document jsoupDoc = Jsoup.parse(resultList.get(i).toString())
            Elements elements = jsoupDoc.select("tr")
            BankTransactionHeaderIndex bankTransactionHeaderIndex = headerIndex(elements.first())
            if (elements.first().select("td").eq(bankTransactionHeaderIndex.transactionDateIndex).text().find("[A-z]{4,}")) {
                elements.remove(0)
            }
            Integer elementCount = elements.size()
            Integer lineCount = 0
            String date = ""
            String description = ""
            String debit = ""
            Date lastTransactionDate = null
            while (lineCount < elementCount) {
                try {
                    Element element = elements.get(lineCount)
                    String transactionDateCell = element.select("td").eq(bankTransactionHeaderIndex.transactionDateIndex).text().trim()
                    String balanceCell = element.select("td").eq(bankTransactionHeaderIndex.balanceAfterTransactionIndex).text().trim()
                    String descriptionCell = element.select("td").eq(bankTransactionHeaderIndex.descriptionIndex).text().trim()
                    boolean isHeaderRow = transactionDateCell.find(headerMap.junk_date) || descriptionCell.find(headerMap.junk_date)
                    boolean isOpeningBalance = descriptionCell.find(headerMap.balance_brought_forward)
                    if (transactionDateCell && balanceCell && !isHeaderRow && !isOpeningBalance) {
                        BankTransactionResponse bankTransactionResponse = new BankTransactionResponse()
                        date = transactionDateCell
                        date = processValue(date)
                        try {
                            bankTransactionResponse.transactionDate = dateFormatFromString(date).parse(date)
                            lastTransactionDate = bankTransactionResponse.transactionDate
                        } catch (Exception e) {
                            if (processedBankStatementVO.bankTransactionList.size() != 0)
                                bankTransactionResponse.transactionDate = processedBankStatementVO.bankTransactionList.last().transactionDate
                            else if (lastTransactionDate)
                                bankTransactionResponse.transactionDate = lastTransactionDate
                        }
                        date = bankTransactionHeaderIndex.valueDateIndex ? element.select("td").eq(bankTransactionHeaderIndex.valueDateIndex).text().trim() : null
                        bankTransactionResponse.valueDate = date ? dateFormatFromString(date).parse(date) : null
                        description = description + " " + descriptionCell
                        bankTransactionResponse.description = description.trim()
                        bankTransactionResponse.remark = bankTransactionHeaderIndex.chequeNoIndex ? element.select("td").eq(bankTransactionHeaderIndex.chequeNoIndex).text() : ""
                        bankTransactionResponse.balanceAfterTransaction = BankUtil.processBalanceAmount(balanceCell)
                        debit = bankTransactionHeaderIndex.debitIndex ? element.select("td").eq(bankTransactionHeaderIndex.debitIndex).text() : null
                        if (bankTransactionHeaderIndex.debitIndex && debit && !debit.find("^[\\s]*(-[\\s]*)?\$")) {
                            bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(debit)
                            bankTransactionResponse.type = Enums.BankTransactionType.DEBIT
                        } else if (bankTransactionHeaderIndex.creditIndex && element.select("td").eq(bankTransactionHeaderIndex.creditIndex).text()) {
                            bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(element.select("td").eq(bankTransactionHeaderIndex.creditIndex).text())
                            bankTransactionResponse.type = Enums.BankTransactionType.CREDIT
                        } else if (bankTransactionHeaderIndex.amountIndex && element.select("td").eq(bankTransactionHeaderIndex.amountIndex).text()) {
                            bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(element.select("td").eq(bankTransactionHeaderIndex.amountIndex).text())
                        }
                        if (bankTransactionHeaderIndex.amountTypeIndex && element.select("td").eq(bankTransactionHeaderIndex.amountTypeIndex).text()) {
                            if (element.select("td").eq(bankTransactionHeaderIndex.amountTypeIndex).text().toLowerCase().find("cr"))
                                bankTransactionResponse.type = Enums.BankTransactionType.CREDIT
                            else
                                bankTransactionResponse.type = Enums.BankTransactionType.DEBIT
                        }
