                        description = ""
                    } else if (!isHeaderRow && !isOpeningBalance && (descriptionCell || balanceCell)) {
                        if (descriptionCell) {
                            description = description + " " + descriptionCell
                        }
                        if (balanceCell && lastTransactionDate && processedBankStatementVO.bankTransactionList.size() > 0) {
                            BankTransactionResponse lastTransaction = processedBankStatementVO.bankTransactionList.last()
                            String newBalance = BankUtil.processBalanceAmount(balanceCell)
                            if (newBalance != lastTransaction.balanceAfterTransaction) {
                                BankTransactionResponse bankTransactionResponse = new BankTransactionResponse()
                                bankTransactionResponse.transactionDate = lastTransactionDate
                                bankTransactionResponse.description = description.trim()
                                bankTransactionResponse.balanceAfterTransaction = newBalance
                                bankTransactionResponse.amount = Math.abs(newBalance - lastTransaction.balanceAfterTransaction)
                                bankTransactionResponse.type = newBalance > lastTransaction.balanceAfterTransaction ? Enums.BankTransactionType.CREDIT : Enums.BankTransactionType.DEBIT
                                bankTransactionResponse.remark = bankTransactionHeaderIndex.chequeNoIndex ? element.select("td").eq(bankTransactionHeaderIndex.chequeNoIndex).text() : ""
                                processedBankStatementVO.bankTransactionList << bankTransactionResponse
                                description = ""
                            }
                        }
                    }
