package com.bankScraper.bank.pdf

import com.bankScraper.AppUtil
import com.bankScraper.Enums
import com.bankScraper.bank.BankOfBarodaUtil
import com.bankScraper.bank.BankTransactionUtil
import com.bankScraper.bank.MainBankService
import com.bankScraper.bank.ProcessedBankStatementVO

class BankOfBarodaPdfService extends MainBankService {

    def grailsApplication

    //    ========================================= General Methods =================================

    public void resolveBankStatementAccountTypeForBasicDetails(ProcessedBankStatementVO processedBankStatementVO) {
        try {
            String fileContent = processedBankStatementVO.processBankStatementCO.textFile.getText('UTF-8')
            if (fileContent.find("BRANCH[\\s]*DETAILS")) {
                log.debug("=== Parsing Bank Of Baroda Downloaded Current Account Statement ***********")
                BankOfBarodaUtil.extractBasicInformationFromDownloadedCurrentAccount(processedBankStatementVO)
            } else {
                log.debug("=== Parsing Bank Of Baroda Downloaded Saving Account Statement ***********")
                BankOfBarodaUtil.extractBasicInformationFromDownloadedSavingAccount(processedBankStatementVO)
            }
        } catch (Exception e) {
            processedBankStatementVO.statementStatus.exceptionStackTrace = AppUtil.getStackTraceAsString(e)
            processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.ERROR
            processedBankStatementVO.statementStatus.message = "Error occurred during parsing pdf file for Bank Of Baroda current bank statement.\n${e.message}"
            log.error(processedBankStatementVO.statementStatus.message, e)
        }
        log.debug("Original Map ===>>>>   ${processedBankStatementVO.basicDetails.properties}")
    }

    public void parsePDFStatementForTransactions(ProcessedBankStatementVO processedBankStatementVO) {
        try {
            String fileContent = processedBankStatementVO.processBankStatementCO.textFile.getText('UTF-8')
            if (fileContent.find("BRANCH[\\s]*DETAILS")) {
                log.debug("=== Parsing Bank Of Baroda Downloaded Current Account Statement for Transactions ***********")
                BankTransactionUtil.extractTransactionsFromHTMLHavingDescriptionBelowDate(processedBankStatementVO)
